.macro module_decap_invntt_POST_STORE_PTR xvec, ptr, off_lo, off_hi
    module_decap_invntt_POST_STORE_PTR_BRANCHFOLD \xvec, \ptr, \off_lo, \off_hi
.endm

.macro module_decap_invntt_LOAD_BRANCHFOLD_CONSTS
    ldr     q10, [x3, #0]     // low normal constants
    ldr     q11, [x3, #16]    // low sqrdmulh precompute
    ldr     q12, [x3, #32]    // high normal constants
    ldr     q13, [x3, #48]    // high sqrdmulh precompute
    add     x3, x3, #64
.endm

.macro module_decap_invntt_POST_STORE_PTR_BRANCHFOLD xvec, ptr, off_lo, off_hi
    /*
     * Branch-constant folded final merge:
     *
     *   out_low =
     *     b0 * F0^k * (1 - ZMINUSZ5INV) / 192
     *   + b1 * F1^k * (1 + ZMINUSZ5INV) / 192
     *
     *   out_high =
     *     b0 * F0^k * ZMINUSZ5INV / 96
     *   - b1 * F1^k * ZMINUSZ5INV / 96
     *
     * That folds untwist, branch merge and final scaling into two fqmul.  The
     * branch lanes are interleaved, so one pairwise add merges both products
     * into [out_low | out_high], and one Barrett reduces the result exactly to
     * the centered representative in [-1728,1728] (|sum| <= 6789 for every
     * int16 input), from which the mod-3 step follows directly.
     */
    module_decap_invntt_LOAD_BRANCHFOLD_CONSTS

    sqrdmulh v17.8h, \xvec\().8h, v11.8h
    mul      v18.8h, \xvec\().8h, v10.8h
    mls      v18.8h, v17.8h, v0.h[0]

    sqrdmulh v20.8h, \xvec\().8h, v13.8h
    mul      v23.8h, \xvec\().8h, v12.8h
    mls      v23.8h, v20.8h, v0.h[0]

    /*
     * merge both branch halves of the low and high products with one
     * add, [lo.b0 + lo.b1 | hi.b0 + hi.b1], and reduce once.  Lane for lane
     * the same values as two ext/add/Barrett sequences, four fewer SIMD ops.
     */
    /* branch lanes are adjacent, so one pairwise add merges
     * both products: [lo.c0..c3 | hi.c0..c3]. */
    addp     v21.8h, v18.8h, v23.8h

    module_decap_invntt_BARRETT_REDUCE v21, v20

    /* fused crepmod3.  The Barrett output is exactly centered in
     * [-1728,1728] for |x| < 29385, so only the mod-3 step remains. */
    sqrdmulh v20.8h, v21.8h, v25.8h
    mls      v21.8h, v20.8h, v26.8h

    str      d21, [\ptr, #\off_lo]
    add      x15, \ptr, #\off_hi
    st1      {v21.d}[1], [x15]
.endm

.macro module_decap_invntt_FUSED_POST_STRIPE ptr0, off0_lo, off0_hi, ptr1, off1_lo, off1_hi, ptr2, off2_lo, off2_hi
    ldr q1, [x8]
    ldr q2, [x9]
    ldr q3, [x10]
    add x8, x8, #16
    add x9, x9, #16
    add x10, x10, #16

    sub      v4.8h, v3.8h, v2.8h
    sqrdmulh v5.8h, v4.8h, v0.h[3]
    mul      v6.8h, v4.8h, v0.h[2]
    mls      v6.8h, v5.8h, v0.h[0]

    /*
     * No reduction after the DFT3: the branchfold fqmul accepts any int16
     * input and ends in an exactly centered Barrett, so representatives here
     * do not affect the output.  The sums stay inside int16 for every product
     * with |x| <= 2458 (interval proof over this kernel).
     */
    add      v7.8h, v1.8h, v2.8h
    add      v7.8h, v7.8h, v3.8h

    sub      v8.8h, v1.8h, v2.8h
    add      v8.8h, v8.8h, v6.8h

    sub      v9.8h, v1.8h, v3.8h
    sub      v9.8h, v9.8h, v6.8h

    module_decap_invntt_POST_STORE_PTR v7, \ptr0, \off0_lo, \off0_hi
    module_decap_invntt_POST_STORE_PTR v8, \ptr1, \off1_lo, \off1_hi
    module_decap_invntt_POST_STORE_PTR v9, \ptr2, \off2_lo, \off2_hi
.endm

.macro module_decap_invntt_RUN_FUSED_POST_STRIPE ptr0, off0_lo, off0_hi, ptr1, off1_lo, off1_hi, ptr2, off2_lo, off2_hi
    module_decap_invntt_FUSED_POST_STRIPE \ptr0, \off0_lo, \off0_hi, \ptr1, \off1_lo, \off1_hi, \ptr2, \off2_lo, \off2_hi
.endm

.macro module_decap_invntt_RUN_FUSED_POST_3STRIPE_GROUP
