    add x13, x0, #256
    module_decap_invntt_RUN_FUSED_POST_LOOP 4

    module_decap_invntt_INVNTT_RESTORE_CALLEE_SAVED_SIMD
    ldr x30, [sp, #64]
    add sp, sp, #module_decap_invntt_INVNTT_STACK_SIZE
    ret

